//! Embedded vector branding used by the decorated QR renderers.
//!
//! Keeping the source geometry here makes the renderer self-contained: no
//! runtime files, fonts, or raster images are required.

use std::collections::HashMap;

use xmltree::{Element, XMLNode};

#[derive(Clone, Copy)]
pub(crate) struct VectorAsset {
    source: &'static str,
    width: f32,
    height: f32,
}

impl VectorAsset {
    const fn new(source: &'static str, width: f32, height: f32) -> Self {
        Self {
            source,
            width,
            height,
        }
    }

    pub(crate) fn insert_at(self, parent: &mut Element, x: f32, y: f32, height: f32, color: &str) {
        let scale = height / self.height;
        let mut group =
            Element::parse(self.source.as_bytes()).expect("embedded branding SVG must be valid");
        remove_source_fills(&mut group);
        group.attributes = HashMap::from([
            ("fill".to_owned(), color.to_owned()),
            (
                "transform".to_owned(),
                format!("translate({x} {y}) scale({scale})"),
            ),
        ]);
        parent.children.push(XMLNode::Element(group));
    }

    pub(crate) fn insert_right_aligned(
        self,
        parent: &mut Element,
        right: f32,
        y: f32,
        height: f32,
        color: &str,
    ) {
        let width = self.width * height / self.height;
        self.insert_at(parent, right - width, y, height, color);
    }
}

fn remove_source_fills(element: &mut Element) {
    element.attributes.remove("fill");

    for child in &mut element.children {
        if let XMLNode::Element(child) = child {
            remove_source_fills(child);
        }
    }
}

